import i18n from 'i18next';
import { initReactI18next } from 'react-i18next';

/**
 * Every locale is the same handful of per-page files (common, home, faq, blog,
 * legal, inapp), merged into one `edb` namespace so t('faq.q1.question') keeps
 * working regardless of which file a key lives in. The six files have no
 * top-level keys in common, so the merge order doesn't matter.
 *
 * Locales are discovered from disk rather than listed here. `import.meta.glob`
 * with `eager: true` is still a static import as far as the bundler is
 * concerned ,  every locale is baked into the bundle, with no lazy chunk for
 * puppeteer to race during prerendering, which is what the old hand-written
 * import list was protecting. Dropping `locales/<code>/*.json` in is now the
 * whole job, provided the code also appears in LANGUAGE_META below.
 */
// The homepage build is inlined into the English `/` only (vite.home.config.js),
// so it bundles English alone; the language switcher reloads to another locale.
const localeFiles = import.meta.env.EDB_HOME
  ? import.meta.glob('./locales/en/*.json', { eager: true, import: 'default' })
  : import.meta.glob('./locales/*/*.json', { eager: true, import: 'default' });

const bundles = {};
for (const [path, contents] of Object.entries(localeFiles)) {
  const lang = /\.\/locales\/([^/]+)\//.exec(path)?.[1];
  if (!lang) continue;
  bundles[lang] = Object.assign(bundles[lang] || {}, contents);
}

/**
 * Display name and flag for every locale the site can ship, in the order the
 * language switcher lists them. A locale appears to users only when it is BOTH
 * listed here and has translation files on disk, so half-finished languages
 * can sit in the repo without being offered to visitors.
 *
 * Codes are two letters because the rest of the pipeline assumes it: the
 * content directories are matched by `[a-z]{2}` in build-content.mjs and
 * vite-plugin-articles.mjs, and the URL prefix is `/<code>`. `pt` is Brazilian
 * Portuguese and `zh` is Simplified Chinese; there is no second variant of
 * either to disambiguate from.
 */
export const LANGUAGE_META = {
  en: { name: 'English', flag: '🇬🇧' },
  ro: { name: 'Română', flag: '🇷🇴' },
  es: { name: 'Español', flag: '🇪🇸' },
  de: { name: 'Deutsch', flag: '🇩🇪' },
  fr: { name: 'Français', flag: '🇫🇷' },
  ja: { name: '日本語', flag: '🇯🇵' },
  pt: { name: 'Português', flag: '🇧🇷' },
  it: { name: 'Italiano', flag: '🇮🇹' },
  zh: { name: '简体中文', flag: '🇨🇳' },
  ko: { name: '한국어', flag: '🇰🇷' },
  ru: { name: 'Русский', flag: '🇷🇺' },
  nl: { name: 'Nederlands', flag: '🇳🇱' },
};

export const defaultLanguage = 'en';

/** Locales with both a LANGUAGE_META entry and translation files present. */
export const supportedLanguages = Object.keys(LANGUAGE_META).filter((code) =>
  bundles[code] || (import.meta.env.EDB_LOCALES || []).includes(code)
);

// Right-to-left locales. None are shipped today; the list stays because
// LanguageSwitcher and the article chrome already branch on it, so adding
// Arabic or Hebrew later is a content job rather than a layout rewrite.
export const rtlLanguages = ['ar', 'he'];

export const changeLanguage = (lng) => i18n.changeLanguage(lng);

/**
 * Matches a leading locale segment on a pathname, e.g. `/ro` or `/de/blog`.
 * Built from supportedLanguages so a new locale can't be left out of the
 * strip-the-prefix logic in the language switcher and the hreflang tags.
 */
export const localePrefixPattern = new RegExp(
  `^/(${supportedLanguages.filter((l) => l !== defaultLanguage).join('|')})(?=/|$)`
);

/** Strips the locale prefix off a pathname, returning the unprefixed route. */
export const stripLocalePrefix = (pathname) => {
  const bare = pathname.replace(localePrefixPattern, '');
  return bare === '' ? '/' : bare;
};

/** The locale a pathname belongs to, or the default. */
export const localeFromPath = (pathname) =>
  localePrefixPattern.exec(pathname)?.[1] || defaultLanguage;

export const initializeI18nSync = (initialLanguage = defaultLanguage) => {
  i18n
    .use(initReactI18next)
    .init({
      resources: Object.fromEntries(
        supportedLanguages.filter((lang) => bundles[lang]).map((lang) => [lang, { edb: bundles[lang] }])
      ),
      lng: initialLanguage,
      fallbackLng: defaultLanguage,
      supportedLngs: supportedLanguages,
      ns: ['edb'],
      defaultNS: 'edb',
      interpolation: {
        escapeValue: false
      },
      react: {
        useSuspense: false
      }
    });

  return i18n;
};

export default i18n;
